import Templates from 'core/templates';
import Modal from 'core/modal';
import * as Repository from './repository';

/**
 * Settings for the AirPay payment gateway
 *
 * @package    paygw_airpay
 * @copyright  2024 Moodle India <support@moodle.com
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

/**
 * Creates and shows a modal that contains a placeholder.
 *
 * core/modal_factory was removed in Moodle 5.2 (its RequireJS dependency 404s, so this whole module
 * never loaded and no payment could start). core/modal is the shape core paygw_paypal uses on
 * 5.1, 5.2 and 5.3 alike.
 *
 * @returns {Promise<Modal>}
 */
const showModalWithPlaceholder = async() => await Modal.create({
    body: await Templates.render('paygw_airpay/airpay_button_placeholder', {}),
    show: true,
    removeOnClose: true,
});

/**
 * Process the payment.
 *
 * @param {string} component Name of the component that the itemId belongs to
 * @param {string} paymentArea The area of the component that the itemId belongs to
 * @param {number} itemId An internal identifier that is used by the component
 * @param {string} description Description of the payment
 * @returns {Promise<string>}
 */
export const process = (component, paymentArea, itemId, description) => {
    return showModalWithPlaceholder()
        .then(modal => {
            return Repository.createPaymentUrl(component, paymentArea, itemId, description)
                .then(url => {
                    location.href = url;
                    // Return a promise that is never going to be resolved.
                    return new Promise(() => null);
                }).catch(e => {
                    modal.hide();
                    // We want to use promise reject here - as that's what core payment stuff expects disable eslint.
                    /* eslint-disable */
                    return Promise.reject(e.message);
                });
        });
};
